// 언어별 문구({ko, en, zh?, ja?}) 고르기: 그 언어의 값 -> (중·일) 영어 원문의 번역표 -> 영어 -> 한국어. 문자열이면 그대로.
function locOf(o, l) {
  if (!o || typeof o !== 'object') return o == null ? '' : String(o);
  if (o[l]) return o[l];
  if (l === 'zh' || l === 'ja') { const t = TR_CJK[l][o.en]; if (t) return t; }
  if (l === 'ko') return o.ko || o.en || '';
  return o.en || o.ko || '';
}
